import React, {useState, useEffect} from 'react'
import {AiOutlineClose, AiOutlineMenu} from 'react-icons/ai'

const Navbar = () => {
    const [nav, setNav] = useState(false)

    const handleNav = () => {
        setNav(!nav)
    }
const [scrolled, setScrolled] = useState(false)

useEffect(() => {
  const handleScroll = () => {
    setScrolled(window.scrollY > 50)
  }

  window.addEventListener('scroll', handleScroll)
  return () => window.removeEventListener('scroll', handleScroll)
}, [])


  return (
    <div>
      <div
  className={`fixed top-0 left-0 w-full z-[99999] h-[90px] flex justify-between items-center
    transition-colors duration-500
    ${scrolled ? 'bg-white/5 backdrop-blur-md text-[#ff058a]' : 'bg-transparent text-white'}
  `}
>
        <h1 className='text-xl font-bold primary-color white-color ml-10'>NIA NUR HIDAYATURROHMAH</h1>
        <ul className='hidden md:flex mr-8'>
            <li className='p-5'><a href='#home'>Home</a></li>
            <li className='p-5'><a href='#about'>About</a></li>
            <li className='p-5'><a href='#work'>Projects</a></li>
            <li className='p-5'><a href='#contact'>Contact</a></li>
        </ul>

        <div onClick={handleNav} className='block md:hidden mr-6'>
            {nav ? <AiOutlineClose size={9}/> : <AiOutlineMenu size={9}/>}
        </div>

        <div className={nav ? 'fixed h-full left-0 top-0 w-[10%] bg-[#5a0e3e] ease-in-out duration-500' 
                                : 'fixed left-[-100%]'}>
            <h1 className='text-3x1 text-gray-400 m-4'>NIA NUR H.</h1>
            <ul className='p-0 text-2x1'>
                <li className='p-2'><a href='#home'>Home</a></li>
                <li className='p-2'><a href='#about'>About</a></li>
                <li className='p-2'><a href='#work'>Projects</a></li>
                <li className='p-2'><a href='#contact'>Contact</a></li>
            </ul>
        </div>  

      </div>
    </div>
  )
}

export default Navbar
