import React from 'react'
import heroImage from '../aset/p2.png'
import { TypeAnimation } from 'react-type-animation'

const Hero = () => {
  return (
    <div className='grid grid-cols-1 sm:grid-cols-3 gap-8 max-w-[1200px] md:h-[70vh] mx-auto py-8' id="home">
        
      <div className='col-span-1 my-auto mx-auto w-[300px] h-auto lg:w-[230px]'>
        <div className='bg-gradient-to-b from-purple-950/40 to-pink-800/40 rounded-xl p-6 border border-gray-400/30'>
          <div className='rounded-lg p-0 border border-black-400/20'>
            <img src={heroImage} alt="profile" className='w-full rounded-lg' />
          </div>
        </div>
      </div>

      <div className='col-span-2 px-5 my-auto'>
        
        <h1 className="text-white text-4xl sm:text-xl  lg:text-6xl font-extrabold">
            <span className="primary-color">
                I'm a
            </span> <br/>
            <TypeAnimation
            sequence={[
                'Web Developer',
                1000,
                'Artificial Intelligence Enthusiast',
                1000,
                'Software Engineer',
                1000,
            ]}
            wrapper="span"
            speed={60}
            repeat={Infinity}
            />
        </h1>
        
        <p className="text-white text-base my-6">
          Passionate about creating amazing web experiences
        </p>
        
        <div className="my-8">
            <a href="https://drive.google.com/file/d/1IK-LixELmvTtiaPBb32CJ8r4ja6Wgkk7/view?usp=drive_link" className="px-6 py-3 w-full border border-gray-400 rounded-xl max-w-[200px] text-white hover:border-white/50 
            bg-gradient-to-b from-purple-950/0 to-purple-950/30 hover:from-indigo-900/40 hover:to-pink-800/40 inset-glow">
              My Resume
            </a>
        </div>
       
      </div>

    </div>
  )
}

export default Hero
