import React from 'react'
import earth from '../aset/earth.png'
import earthTopology from '../aset/earth-topology.png'
import Globe from 'react-globe.gl'


const About = () => {
  const globeEl = React.useRef();

  React.useEffect(() => {
    if (globeEl.current) {
      globeEl.current.controls().autoRotate = true;
      globeEl.current.controls().autoRotateSpeed = 2;
    }
  }, []);

  return (
    <div className="text-white max-w-[1200px] mx-auto my-0 px-0" id="about">
      <div className='md:grid md:grid-cols-2 md:gap-12 items-center'>
        
        <div className="mt-4 md:mt-0 text-left flex flex-col h-full justify-center py-6 md:py-0">
          <div className="mx-6">
            <h2 className="text-4xl font-bold mb-6 bg-gradient-to-r primary-color bg-clip-text text-transparent">
              About Me
            </h2>
            <div className="space-y-4 text-gray-300 leading-relaxed">
              <p className="text-base">
                Hi👋 You can call me Nia. I’m interested in building things related to Software Engineering and Artificial Intelligence.
              </p>
              <p className="text-base">
                I <span className="text-blue-400 font-semibold">enjoy</span> exploring how technology interacts with humans, with a growing curiosity about psychology, biology, and how different ideas begin to connect.
              </p>
              <p className="text-base">
                Most of my projects start with a question about <span className='italic'>what needs to be explored or improved,</span> which helps guide the way I build things.
              </p>
              <p className="text-base">
                By understanding goals, I<span className="text-purple-400 font-semibold"> help </span> people develop modern digital products using the <span className='font-bold'>right technologies for the right purpose.</span>
              </p>
              <p className="text-base italic text-gray-400">
                I love combining art and engineering in shaping digital experiences.
              </p>
            </div>
          </div>
        </div>

        <div className="flex justify-center items-center">
          <div className="flex items-center justify-center overflow-hidden">
            <Globe
              ref={globeEl}
              height={680}
              width={680}
              backgroundColor="rgba(0, 0, 0, 0)"
              showAtmosphere
              globeImageUrl={earth}
              bumpImageUrl={earthTopology}
              
              onGlobeReady={() => {
                if (globeEl.current) {
                  globeEl.current.controls().enableZoom = false;
                    

  
                  
                }
              }}
            />
          </div>
        </div>

        

      </div>
    </div>
  )
}

export default About
